package dev.jarofcucumbers.prscraft;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.item.component.CustomData;
import net.neoforged.neoforge.network.PacketDistributor;
import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
/** A physical notebook contains up to eight immutable captures and editable annotations, never live pointers. */
public final class NotebookNetwork{
    public record Request(int slot,int index,String action,String title,String description,BlockPos target,int virtualNode) implements CustomPacketPayload{
        public static final Type<Request> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath(PRSCraft.ID,"notebook"));public static final StreamCodec<RegistryFriendlyByteBuf,Request> CODEC=new StreamCodec<>(){public Request decode(RegistryFriendlyByteBuf b){return new Request(b.readInt(),b.readInt(),b.readUtf(24),b.readUtf(64),b.readUtf(2048),b.readBlockPos(),b.readInt());}public void encode(RegistryFriendlyByteBuf b,Request p){b.writeInt(p.slot);b.writeInt(p.index);b.writeUtf(p.action,24);b.writeUtf(p.title,64);b.writeUtf(p.description,2048);b.writeBlockPos(p.target);b.writeInt(p.virtualNode);}};public Type<? extends CustomPacketPayload> type(){return TYPE;}
    }
    public static int find(ServerPlayer p){int selected=p.getInventory().selected;if(p.getInventory().getItem(selected).is(PRSCraft.NOTEBOOK.get()))return selected;if(p.getOffhandItem().is(PRSCraft.NOTEBOOK.get()))return 40;for(int i=0;i<p.getInventory().getContainerSize();i++)if(p.getInventory().getItem(i).is(PRSCraft.NOTEBOOK.get()))return i;return -1;}
    private static ItemStack notebook(ServerPlayer p,int slot){return slot>=0&&slot<p.getInventory().getContainerSize()&&p.getInventory().getItem(slot).is(PRSCraft.NOTEBOOK.get())?p.getInventory().getItem(slot):ItemStack.EMPTY;}
    public static CompoundTag data(ItemStack stack){var component=stack.get(DataComponents.CUSTOM_DATA);return component==null?new CompoundTag():component.copyTag();}
    private static void store(ServerPlayer p,int slot,CompoundTag tag){notebook(p,slot).set(DataComponents.CUSTOM_DATA,CustomData.of(tag));p.inventoryMenu.broadcastChanges();}
    public static void register(RegisterPayloadHandlersEvent e){e.registrar("1").playToServer(Request.TYPE,Request.CODEC,(request,context)->context.enqueueWork(()->{if(!(context.player() instanceof ServerPlayer player))return;if(request.action.equals("capture_sim")){int slot=find(player);if(slot<0)player.displayClientMessage(net.minecraft.network.chat.Component.translatable("error.prscraft.notebook_required"),true);else capture(player,slot,request.target,request.virtualNode);return;}if(notebook(player,request.slot).isEmpty())return;long tick=player.level().getGameTime();var budget=player.getPersistentData();if(budget.contains("prscraft_note_tick")&&tick-budget.getLong("prscraft_note_tick")<2)return;budget.putLong("prscraft_note_tick",tick);String error="";try{var tag=data(notebook(player,request.slot));var list=tag.getList("experiments",10);if(request.action.equals("capture")){capture(player,request.slot,request.target,request.virtualNode);return;}if(request.action.equals("new")){if(list.size()>=8)throw new IllegalArgumentException("notebook_full");var entry=new CompoundTag();entry.putString("title","Experiment "+(list.size()+1));entry.putString("description","");NotebookRecords.append(list,entry);}else{if(request.index<0||request.index>=list.size())throw new IllegalArgumentException("notebook_entry");var entry=list.getCompound(request.index);switch(request.action){case "save"->{if(request.title.length()>64||request.description.length()>2048)throw new IllegalArgumentException("notebook_entry");NotebookRecords.annotate(entry,request.title,request.description);}case "remove"->list.remove(request.index);case "template"->{if(!entry.contains("template"))throw new IllegalArgumentException("notebook_capture");int paper=-1;for(int i=0;i<player.getInventory().getContainerSize();i++)if(player.getInventory().getItem(i).is(Items.PAPER)){paper=i;break;}if(paper<0)throw new IllegalArgumentException("notebook_paper");player.getInventory().getItem(paper).shrink(1);var result=new ItemStack(PRSCraft.TEMPLATE.get());result.set(DataComponents.CUSTOM_DATA,CustomData.of(entry.getCompound("template")));result.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal(entry.getString("title")));result.set(DataComponents.CUSTOM_MODEL_DATA,new net.minecraft.world.item.component.CustomModelData(TemplateItem.model(entry.getCompound("template").getString("kind"),RadioSettings.read(entry.getCompound("template").getCompound("settings")))));if(!player.getInventory().add(result))player.drop(result,false);}default->throw new IllegalArgumentException("notebook_entry");}}tag.put("experiments",list);store(player,request.slot,tag);}catch(IllegalArgumentException ex){error=ex.getMessage();}open(player,request.slot,false,error);}));}
    public static void capture(ServerPlayer p,int slot,BlockPos target,int virtualNode){if(notebook(p,slot).isEmpty())return;String error="";try{var tag=data(notebook(p,slot));var entries=tag.getList("experiments",10);if(entries.size()>=8)throw new IllegalArgumentException("notebook_full");if(p.distanceToSqr(target.getX()+.5,target.getY()+.5,target.getZ()+.5)>64||!p.serverLevel().hasChunkAt(target))throw new IllegalArgumentException("notebook_capture");RadioBlockEntity radio;CompoundTag capture;if(virtualNode>=0){var sim=SimulatorNetwork.available(p,target);if(sim==null)throw new IllegalArgumentException("notebook_capture");var world=sim.document().world(p.level().registryAccess(),p.level().getGameTime());if(!(world.getBlockEntity(SimulatorDocument.position(virtualNode)) instanceof RadioBlockEntity r))throw new IllegalArgumentException("notebook_capture");radio=r;capture=CircuitCapture.capture(world,r.getBlockPos());}else{if(!(p.level().getBlockEntity(target) instanceof RadioBlockEntity r))throw new IllegalArgumentException("notebook_capture");radio=r;capture=RadioCapture.capture(p.level(),target);}if(capture.getIntArray("received").length!=512)throw new IllegalArgumentException("notebook_capture");var entry=new CompoundTag();entry.putString("title","Experiment "+(entries.size()+1));entry.putString("description","");entry.put("capture",capture.copy());entry.put("template",DeviceConfiguration.template(radio));if(radio.codebook()!=null)entry.putString("codebook",CodebookCardItem.mapping(radio.media.getStackInSlot(2)));entry.putLong("tick",p.level().getGameTime());entry.putString("dimension",p.level().dimension().location().toString());entry.putLong("position",target.asLong());entry.putBoolean("simulated",virtualNode>=0);NotebookRecords.append(entries,entry);Milestones.award(p,"protocol_entry");tag.put("experiments",entries);store(p,slot,tag);}catch(IllegalArgumentException ex){error=ex.getMessage();}open(p,slot,true,error);}
    public static void open(ServerPlayer p,int slot,boolean open,String error){var stack=notebook(p,slot);if(stack.isEmpty())return;var data=data(stack);data.putInt("slot",slot);data.putString("kind","research_notebook");data.putString("error",error);PacketDistributor.sendToPlayer(p,new RadioNetwork.Snapshot(p.blockPosition(),open,data));}
}
